    typ=m.get('type')
    if typ=='assistant':
        print("\n=== ASSISTANT", m['id'], "===")
        for c in m.get('content',[]):
            t=c.get('type')
            if t=='text': print("TEXT:",c.get('text','')[:1200])
            elif t=='reasoning': print("REASON:",c.get('text','')[:600])
            elif t=='tool':
                print("TOOL:",c.get('name'))
                print(" IN:",json.dumps(c.get('state',{}).get('input',{}),ensure_ascii=False)[:600])
                out=c.get('state',{}).get('output')
                print(" OUT:",str(out)[:600])
    elif typ=='user':
        print("\n=== USER:", m.get('text','')[:500])
    else:
        print("\n=== ",typ, json.dumps(m,ensure_ascii=False)[:300])
EOF

